import{_ as t,o as r,c as n,a3 as i}from"./chunks/framework.B5WAEDB7.js";const c=JSON.parse('{"title":"Mehrseitige Formulare","description":"Lange Formulare auf mehrere Seiten aufteilen.","frontmatter":{"title":"Mehrseitige Formulare","description":"Lange Formulare auf mehrere Seiten aufteilen."},"headers":[],"relativePath":"formulare/mehrseitige-formulare.md","filePath":"formulare/mehrseitige-formulare.md","lastUpdated":1786086822000}'),a={name:"formulare/mehrseitige-formulare.md"};function s(l,e,h,o,d,u){return r(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="mehrseitige-formulare" tabindex="-1">Mehrseitige Formulare <a class="header-anchor" href="#mehrseitige-formulare" aria-label="Permalink to &quot;Mehrseitige Formulare&quot;">​</a></h1><p>Ein Formular kann aus mehreren <strong>Formularseiten</strong> bestehen. Ausfüllende arbeiten sie nacheinander durch.</p><div class="tip custom-block"><p class="custom-block-title">Nicht mit Portal-Seiten verwechseln</p><p>Eine <em>Formularseite</em> ist ein Abschnitt innerhalb eines Formulars. Sie hat nichts mit einer <a href="/seiten/was-sind-seiten">Seite</a> im Sinne von Portalen zu tun, auch wenn beide „Seite&quot; heißen.</p></div><h2 id="seite-hinzufugen" tabindex="-1">Seite hinzufügen <a class="header-anchor" href="#seite-hinzufugen" aria-label="Permalink to &quot;Seite hinzufügen&quot;">​</a></h2><p>Im Reiter <strong>Seiten</strong> des Formular-Editors: <strong>Seite zum Formular hinzufügen</strong>.</p><p>Jede Seite bekommt eigene Felder und Textblöcke. Über <strong>Seite entfernen</strong> löschen Sie eine wieder.</p><div class="warning custom-block"><p class="custom-block-title">Felder wandern nicht automatisch mit</p><p>Beim Entfernen einer Seite verschwinden auch die darauf liegenden Felder aus dem Formular. Die Daten im Grid bleiben unberührt — aber die Felder werden nicht mehr abgefragt.</p></div><h2 id="was-ausfullende-sehen" tabindex="-1">Was Ausfüllende sehen <a class="header-anchor" href="#was-ausfullende-sehen" aria-label="Permalink to &quot;Was Ausfüllende sehen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Beschriftung</th></tr></thead><tbody><tr><td>Zur nächsten Seite</td><td><strong>Weiter</strong></td></tr><tr><td>Zur vorherigen Seite</td><td><strong>zurück</strong></td></tr><tr><td>Auf der letzten Seite</td><td><strong>Absenden</strong></td></tr></tbody></table><p>Abgeschickt wird <strong>erst am Ende</strong>. Bis dahin sind die Eingaben nicht im Grid.</p><div class="warning custom-block"><p class="custom-block-title">Ohne „Speichern um später fortzufahren&quot; gehen Eingaben verloren</p><p>Schließt jemand das Formular auf Seite 3 von 5, ist alles weg. Bei längeren Formularen sollten Sie deshalb <em>Speichern um später fortzufahren</em> einschalten.</p><p>→ <a href="/formulare/speichern-und-fortsetzen">Speichern und später fortsetzen</a></p></div><h2 id="wann-sich-mehrere-seiten-lohnen" tabindex="-1">Wann sich mehrere Seiten lohnen <a class="header-anchor" href="#wann-sich-mehrere-seiten-lohnen" aria-label="Permalink to &quot;Wann sich mehrere Seiten lohnen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Empfehlung</th></tr></thead><tbody><tr><td>Bis etwa 10 Felder</td><td>Eine Seite, gegliedert mit Überschriften-Textblöcken</td></tr><tr><td>Mehr als 10 Felder</td><td>Mehrere Seiten</td></tr><tr><td>Thematisch getrennte Bereiche</td><td>Mehrere Seiten, eine je Thema</td></tr><tr><td>Formular für Mobilgeräte</td><td>Eher mehrere kurze Seiten</td></tr><tr><td>Auto-Absenden aktiv</td><td>Eine Seite — mehrere ergeben keinen Sinn</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Nach Themen schneiden, nicht nach Feldanzahl</p><p>Gute Schnitte sind inhaltlich: „Ihre Kontaktdaten&quot;, „Ihr Anliegen&quot;, „Anhänge&quot;. Schlechte Schnitte trennen Zusammengehöriges — etwa Straße auf Seite 1 und Postleitzahl auf Seite 2.</p><p>Ein Überschriften-Textblock oben auf jeder Seite sagt Ausfüllenden, wo sie gerade sind.</p></div><div class="tip custom-block"><p class="custom-block-title">Pflichtfelder nach vorn</p><p>Was Sie unbedingt brauchen, gehört auf die ersten Seiten. Bricht jemand ab, haben Sie zwar keinen Eintrag — aber bei aktiviertem Speichern wenigstens die wichtigen Angaben zur Wiederaufnahme.</p></div><h2 id="zusammenspiel-mit-anderen-einstellungen" tabindex="-1">Zusammenspiel mit anderen Einstellungen <a class="header-anchor" href="#zusammenspiel-mit-anderen-einstellungen" aria-label="Permalink to &quot;Zusammenspiel mit anderen Einstellungen&quot;">​</a></h2><p><strong>Bedingte Anzeige</strong> je Feld gibt es im Formular-Builder nicht. Wollen Sie Felder abhängig von einer Eingabe ein- und ausblenden, brauchen Sie eine <a href="/seiten/was-sind-seiten">Seite</a> mit <a href="/seiten/sichtbarkeit">bedingter Sichtbarkeit</a> statt eines Formulars.</p><p><strong>Mehrsprachigkeit</strong> wirkt über alle Formularseiten hinweg. → <a href="/formulare/mehrsprachig">Mehrsprachige Formulare</a></p><p><strong>Eingebettete Formulare</strong> brauchen bei mehreren Seiten <em>Höhe automatisch anpassen</em>, sonst entsteht ein Scrollbalken im Rahmen. → <a href="/formulare/formular-teilen">Formular teilen</a></p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/formulare/formular-erstellen">Formular erstellen</a></li><li><a href="/formulare/speichern-und-fortsetzen">Speichern und später fortsetzen</a></li><li><a href="/formulare/felder-konfigurieren">Felder konfigurieren</a></li></ul>',21)])])}const g=t(a,[["render",s]]);export{c as __pageData,g as default};
